    /// <summary>
    /// Verifies that <see cref="DateOnly.MaxValue" /> yields <c>9999-10-01</c> (Q4 of year 9999) for the January-to-December quarter start.
    /// </summary>
    [TestMethod]
    public void FirstDateOfQuarter_WhenInputIsMaxValue_ShouldReturnExpectedDate()
    {
        var actual = DateOnly.MaxValue.FirstDateOfQuarter(CalendarQuarterDefinition.JanuaryToDecember);
        Assert.AreEqual(new DateOnly(9999, 10, 1), actual); // Q4 of 9999
    }

